-- Garante que TODA permissao definida no AuthSeed exista como linha em `permissions`.
-- Chaves adicionadas ao codigo depois da primeira instalacao (ex.: regulations.version_history)
-- nunca ganhavam linha em producao porque so o AuthSeed (dev) as cria, e ficavam sem dono ate
-- alguma migration especifica as inserir. Isso deixava ate o administrador sem a permissao
-- (ex.: Historico de versoes do regulamento retornava 403 mesmo para admin).
ON DUPLICATE KEY UPDATE name = VALUES(name), description = VALUES(description), module = VALUES(module), updated_at = VALUES(updated_at);

-- Administrador recebe toda permissao existente (definicao do perfil: acesso global).
SELECT r.id, p.id, NOW() FROM roles r CROSS JOIN permissions p WHERE r.`key` = 'administrator';

-- Organizador recebe tudo, exceto a lista global fixa (mesma exclusao da migration 0050).
SELECT r.id, p.id, NOW()
FROM roles r
CROSS JOIN permissions p
WHERE r.`key` = 'organizer'
  AND p.`key` NOT IN (
    'system.configure',
    'users.view', 'users.create', 'users.update', 'users.deactivate', 'users.delete', 'users.manage_roles',
    'audit.view',
    'championships.create', 'championships.archive',
    'seasons.manage', 'categories.manage', 'positions.manage', 'tactical_formations.manage',
    'backup.view', 'backup.run', 'backup.download', 'backup.retry', 'backup.delete', 'backup.restore', 'backup.configure',
    'retention.view', 'retention.manage', 'retention.archive', 'retention.restore', 'retention.purge',
    'simulation.manage',
    'match_publication.run'
  );
